-- Every data-source name is usable only through its actual new input receipt.
CREATE TABLE datasource_name_versions (datasource_id TEXT PRIMARY KEY, revision BIGINT NOT NULL CHECK(revision > 0));
CREATE TABLE datasource_name_inputs (id TEXT PRIMARY KEY, datasource_id TEXT NOT NULL, tenant_id BIGINT NOT NULL, knowledge_base_id TEXT NOT NULL, revision BIGINT NOT NULL CHECK(revision > 0), body_digest TEXT NOT NULL CHECK(length(body_digest)=64), origin_kind TEXT NOT NULL CHECK(origin_kind IN ('human','pairing_configuration')), actual_inputs TEXT NOT NULL, input_digest TEXT NOT NULL CHECK(length(input_digest)=64));
CREATE INDEX datasource_name_inputs_current ON datasource_name_inputs(datasource_id,revision);
INSERT INTO datasource_name_versions(datasource_id,revision) SELECT id,1 FROM data_sources;
CREATE TRIGGER datasource_name_input_immutable_update BEFORE UPDATE ON datasource_name_inputs BEGIN SELECT RAISE(ABORT,'immutable datasource name input'); END;
CREATE TRIGGER datasource_name_input_immutable_delete BEFORE DELETE ON datasource_name_inputs BEGIN SELECT RAISE(ABORT,'immutable datasource name input'); END;
CREATE TRIGGER datasource_name_input_version_insert AFTER INSERT ON data_sources BEGIN INSERT INTO datasource_name_versions(datasource_id,revision) VALUES(NEW.id,1) ON CONFLICT(datasource_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER datasource_name_input_version_update AFTER UPDATE ON data_sources WHEN OLD.tenant_id IS NOT NEW.tenant_id OR OLD.knowledge_base_id IS NOT NEW.knowledge_base_id OR OLD.name IS NOT NEW.name OR OLD.type IS NOT NEW.type OR OLD.deleted_at IS NOT NEW.deleted_at BEGIN INSERT INTO datasource_name_versions(datasource_id,revision) VALUES(NEW.id,1) ON CONFLICT(datasource_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER datasource_name_input_version_delete AFTER DELETE ON data_sources BEGIN INSERT INTO datasource_name_versions(datasource_id,revision) VALUES(OLD.id,1) ON CONFLICT(datasource_id) DO UPDATE SET revision=revision+1; END;

CREATE TABLE nextcloud_upload_source_versions(datasource_id TEXT PRIMARY KEY, revision BIGINT NOT NULL CHECK(revision > 0));
INSERT INTO nextcloud_upload_source_versions(datasource_id,revision) SELECT id,1 FROM data_sources WHERE type='nextcloud';
CREATE TABLE nextcloud_original_upload_inputs(knowledge_id TEXT PRIMARY KEY, tenant_id BIGINT NOT NULL, knowledge_base_id TEXT NOT NULL, datasource_id TEXT NOT NULL, source_revision BIGINT NOT NULL CHECK(source_revision > 0), config_revision BIGINT NOT NULL CHECK(config_revision > 0), config_digest TEXT NOT NULL CHECK(length(config_digest)=64), root_digest TEXT NOT NULL CHECK(length(root_digest)=64), root_revision BIGINT NOT NULL CHECK(root_revision > 0), routing_revision BIGINT NOT NULL CHECK(routing_revision > 0), routing_digest TEXT NOT NULL CHECK(length(routing_digest)=64), tenant_revision BIGINT NOT NULL CHECK(tenant_revision > 0), tenant_digest TEXT NOT NULL CHECK(length(tenant_digest)=64), artifact_digest TEXT NOT NULL CHECK(length(artifact_digest)=64), actual_inputs TEXT NOT NULL, input_digest TEXT NOT NULL CHECK(length(input_digest)=64));
CREATE TRIGGER nextcloud_original_upload_immutable_update BEFORE UPDATE ON nextcloud_original_upload_inputs BEGIN SELECT RAISE(ABORT,'immutable actual original upload'); END;
CREATE TRIGGER nextcloud_original_upload_immutable_delete BEFORE DELETE ON nextcloud_original_upload_inputs BEGIN SELECT RAISE(ABORT,'immutable actual original upload'); END;
CREATE TRIGGER nextcloud_upload_source_insert AFTER INSERT ON data_sources WHEN NEW.type='nextcloud' BEGIN INSERT INTO nextcloud_upload_source_versions(datasource_id,revision) VALUES(NEW.id,1) ON CONFLICT(datasource_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nextcloud_upload_source_update AFTER UPDATE ON data_sources WHEN OLD.type='nextcloud' OR NEW.type='nextcloud' BEGIN INSERT INTO nextcloud_upload_source_versions(datasource_id,revision) SELECT NEW.id,1 WHERE OLD.tenant_id IS NOT NEW.tenant_id OR OLD.knowledge_base_id IS NOT NEW.knowledge_base_id OR OLD.type IS NOT NEW.type OR OLD.config IS NOT NEW.config OR OLD.status IS NOT NEW.status OR OLD.deleted_at IS NOT NEW.deleted_at ON CONFLICT(datasource_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nextcloud_upload_source_delete AFTER DELETE ON data_sources WHEN OLD.type='nextcloud' BEGIN INSERT INTO nextcloud_upload_source_versions(datasource_id,revision) VALUES(OLD.id,1) ON CONFLICT(datasource_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nextcloud_upload_pair_insert AFTER INSERT ON nextcloud_source_pairings BEGIN INSERT INTO nextcloud_upload_source_versions(datasource_id,revision) VALUES(NEW.datasource_id,1) ON CONFLICT(datasource_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nextcloud_upload_pair_update AFTER UPDATE ON nextcloud_source_pairings WHEN OLD.tenant_id IS NOT NEW.tenant_id OR OLD.knowledge_base_id IS NOT NEW.knowledge_base_id OR OLD.datasource_id IS NOT NEW.datasource_id OR OLD.nextcloud_instance_id IS NOT NEW.nextcloud_instance_id OR OLD.binding_id IS NOT NEW.binding_id OR OLD.datasource_base_url IS NOT NEW.datasource_base_url OR OLD.datasource_config_sha256 IS NOT NEW.datasource_config_sha256 OR OLD.publication_epoch IS NOT NEW.publication_epoch OR OLD.state IS NOT NEW.state BEGIN INSERT INTO nextcloud_upload_source_versions(datasource_id,revision) VALUES(OLD.datasource_id,1) ON CONFLICT(datasource_id) DO UPDATE SET revision=revision+1; INSERT INTO nextcloud_upload_source_versions(datasource_id,revision) SELECT NEW.datasource_id,1 WHERE NEW.datasource_id IS NOT OLD.datasource_id ON CONFLICT(datasource_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nextcloud_upload_pair_delete AFTER DELETE ON nextcloud_source_pairings BEGIN INSERT INTO nextcloud_upload_source_versions(datasource_id,revision) VALUES(OLD.datasource_id,1) ON CONFLICT(datasource_id) DO UPDATE SET revision=revision+1; END;

-- Exact private transition of one question producer's own metadata output.
CREATE TABLE knowledge_question_metadata_outputs(chunk_id TEXT NOT NULL,admission_id TEXT NOT NULL,producer_input_id TEXT NOT NULL,previous_revision BIGINT NOT NULL,previous_metadata_digest TEXT NOT NULL,previous_body_digest TEXT NOT NULL,result_revision BIGINT NOT NULL,result_metadata_digest TEXT NOT NULL,result_body_digest TEXT NOT NULL,PRIMARY KEY(chunk_id,result_revision));
CREATE TRIGGER knowledge_question_metadata_output_immutable_update BEFORE UPDATE ON knowledge_question_metadata_outputs BEGIN SELECT RAISE(ABORT,'immutable actual question metadata result'); END;
CREATE TRIGGER knowledge_question_metadata_output_immutable_delete BEFORE DELETE ON knowledge_question_metadata_outputs BEGIN SELECT RAISE(ABORT,'immutable actual question metadata result'); END;
